-- =====================================================================
-- La Valenciana · base de datos de la tienda y del panel (Trastienda)
-- Pegar entero en Supabase → SQL Editor → New query → Run.
-- Se puede ejecutar más de una vez sin estropear nada.
-- ANTES de ejecutarlo, cree su usuario en Authentication → Users → Add user:
-- al final del script, todos los usuarios que existan pasan a ser administradores.
-- =====================================================================

-- ---------- TABLAS ----------
create table if not exists categorias (
  id text primary key, nombre text not null, texto text, orden int default 0
);
create table if not exists subcategorias (
  id text primary key, cat text not null references categorias(id) on update cascade,
  nombre text not null, texto text, orden int default 0
);
create table if not exists productos (
  id text primary key,
  cat text not null references categorias(id) on update cascade,
  sub text not null references subcategorias(id) on update cascade,
  nombre text not null,
  precio numeric(10,2) not null check (precio > 0),
  coste numeric(10,2),                       -- solo lo ven los administradores
  icono text, descripcion text,
  variantes jsonb not null default '[]',     -- [{"n":"Rojo","c":"#C0392B"}]
  tipo_var text, medidas jsonb not null default '[]', tipo_medida text,
  por_metro boolean not null default false,
  precios jsonb, etiqueta text, detalles jsonb not null default '[]',
  destacado boolean not null default false, novedad boolean not null default false,
  visible boolean not null default true,
  oferta int check (oferta between 1 and 90),  -- % de rebaja
  uds numeric(10,2) not null default 0,        -- unidades (o metros) en la tienda
  umbral numeric(10,2) not null default 5,     -- a partir de aquí: «Quedan pocas»
  orden int default 0,
  actualizado timestamptz not null default now()
);
create table if not exists pedidos (
  ref text primary key,
  creado timestamptz not null default now(),
  cliente text not null, tel text, email text,
  direccion text, localidad text, cp text,
  entrega text not null check (entrega in ('casa','tienda')),
  canal text not null check (canal in ('tarjeta','whatsapp','correo','tienda')),
  lineas jsonb not null,                      -- [{id,nombre,version,q,precio}]
  subtotal numeric(10,2) not null, envio numeric(10,2) not null default 0,
  descuento numeric(10,2) not null default 0, codigo text,
  total numeric(10,2) not null,
  estado text not null default 'cobrar'
    check (estado in ('cobrar','preparar','enviado','recoger','entregado','cancelado')),
  paypal_id text, notas text, nota_interna text
);
create index if not exists pedidos_creado on pedidos (creado desc);
create table if not exists movimientos (
  id bigint generated always as identity primary key,
  t timestamptz not null default now(),
  producto text references productos(id) on update cascade on delete set null,
  cantidad numeric(10,2) not null, motivo text, quien text
);
create table if not exists ajustes (clave text primary key, valor jsonb);
create table if not exists codigos (
  codigo text primary key, tipo text not null check (tipo in ('%','€')),
  valor numeric(10,2) not null, activo boolean not null default true,
  hasta date, usos int not null default 0
);
create table if not exists registro (
  id bigint generated always as identity primary key,
  t timestamptz not null default now(), quien text, texto text not null
);
create table if not exists admins (
  user_id uuid primary key references auth.users(id) on delete cascade,
  nombre text, rol text not null default 'admin' check (rol in ('admin','pedidos','consulta'))
);

-- ---------- ¿QUIÉN ES ADMINISTRADOR? ----------
create or replace function es_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from admins where user_id = auth.uid());
$$;
create or replace function puede_editar() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from admins where user_id = auth.uid() and rol in ('admin','pedidos'));
$$;

-- ---------- PERMISOS (Row Level Security) ----------
-- La tienda (visitantes sin sesión) solo puede LEER el catálogo visible y los ajustes.
-- Los pedidos no se escriben directamente: pasan por la función crear_pedido().
alter table categorias    enable row level security;
alter table subcategorias enable row level security;
alter table productos     enable row level security;
alter table pedidos       enable row level security;
alter table movimientos   enable row level security;
alter table ajustes       enable row level security;
alter table codigos       enable row level security;
alter table registro      enable row level security;
alter table admins        enable row level security;

do $$ declare t text; begin
  foreach t in array array['categorias','subcategorias','productos','pedidos','movimientos','ajustes','codigos','registro'] loop
    execute format('drop policy if exists "admin lee" on %I', t);
    execute format('drop policy if exists "admin escribe" on %I', t);
    execute format('create policy "admin lee" on %I for select to authenticated using (es_admin())', t);
    execute format('create policy "admin escribe" on %I for all to authenticated using (puede_editar()) with check (puede_editar())', t);
  end loop;
end $$;
drop policy if exists "admin ve admins" on admins;
create policy "admin ve admins" on admins for select to authenticated using (es_admin());

drop policy if exists "tienda lee" on categorias;
create policy "tienda lee" on categorias for select to anon using (true);
drop policy if exists "tienda lee" on subcategorias;
create policy "tienda lee" on subcategorias for select to anon using (true);
drop policy if exists "tienda lee" on ajustes;
create policy "tienda lee" on ajustes for select to anon using (true);
drop policy if exists "tienda lee" on productos;
create policy "tienda lee" on productos for select to anon using (visible);
-- El coste es interno: la tienda no puede leer esa columna.
revoke select on productos from anon;
grant select (id,cat,sub,nombre,precio,icono,descripcion,variantes,tipo_var,medidas,tipo_medida,por_metro,
  precios,etiqueta,detalles,destacado,novedad,visible,oferta,uds,umbral,orden,actualizado) on productos to anon;

-- ---------- FECHA DE ÚLTIMO CAMBIO ----------
create or replace function tocar() returns trigger language plpgsql as $$
begin new.actualizado = now(); return new; end $$;
drop trigger if exists productos_tocar on productos;
create trigger productos_tocar before update on productos for each row execute function tocar();

-- ---------- CREAR PEDIDO (lo llama la tienda) ----------
-- Recalcula precios y envío con los datos de la base (la clienta no puede cambiarlos),
-- comprueba stock, lo descuenta y devuelve la referencia y el total.
create or replace function crear_pedido(datos jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  l jsonb; p productos%rowtype; q numeric; precio numeric;
  sub numeric := 0; env numeric := 0; desc_ numeric := 0; lineas jsonb := '[]';
  r text; aj_envio numeric; aj_gratis numeric; c codigos%rowtype; vac boolean;
begin
  select coalesce((valor)::boolean,false) into vac from ajustes where clave='vacaciones';
  if vac then raise exception 'La tienda está de vacaciones y no admite pedidos ahora mismo.'; end if;
  if coalesce(trim(datos->>'cliente'),'') = '' then raise exception 'Falta el nombre.'; end if;
  if jsonb_array_length(coalesce(datos->'lineas','[]')) = 0 then raise exception 'La cesta está vacía.'; end if;

  for l in select * from jsonb_array_elements(datos->'lineas') loop
    select * into p from productos where id = l->>'id' and visible for update;
    if not found then raise exception 'Un artículo ya no está disponible: %', l->>'id'; end if;
    q := (l->>'q')::numeric;
    if q is null or q <= 0 or q > 50 then raise exception 'Cantidad no válida en %', p.nombre; end if;
    if p.uds < q then raise exception 'No queda bastante de «%» (quedan %).', p.nombre, p.uds; end if;
    precio := coalesce((p.precios->>(l->>'version'))::numeric, p.precio);
    if p.oferta is not null then precio := round(precio * (100 - p.oferta) / 100, 2); end if;
    sub := sub + round(precio * q, 2);
    lineas := lineas || jsonb_build_object('id',p.id,'nombre',p.nombre,'version',l->>'version','q',q,'precio',precio);
    update productos set uds = uds - q where id = p.id;
    insert into movimientos (producto,cantidad,motivo,quien) values (p.id,-q,'Venta web','Tienda');
  end loop;

  if datos->>'codigo' is not null then
    select * into c from codigos where codigo = upper(datos->>'codigo') and activo and (hasta is null or hasta >= current_date);
    if found then
      desc_ := case when c.tipo='%' then round(sub * c.valor / 100, 2) else least(c.valor, sub) end;
      update codigos set usos = usos + 1 where codigo = c.codigo;
    end if;
  end if;

  if datos->>'entrega' = 'casa' then
    select (valor)::numeric into aj_envio from ajustes where clave='envio';
    select (valor)::numeric into aj_gratis from ajustes where clave='envioGratis';
    env := case when sub - desc_ >= coalesce(aj_gratis,50) then 0 else coalesce(aj_envio,4.95) end;
  end if;

  r := 'LV-' || to_char(now() at time zone 'Europe/Madrid','YYMMDD') || '-' || upper(substr(md5(random()::text),1,4));
  insert into pedidos (ref,cliente,tel,email,direccion,localidad,cp,entrega,canal,lineas,subtotal,envio,descuento,codigo,total,paypal_id,notas)
  values (r, datos->>'cliente', datos->>'tel', datos->>'email', datos->>'direccion', datos->>'localidad', datos->>'cp',
          coalesce(datos->>'entrega','tienda'), coalesce(datos->>'canal','whatsapp'), lineas, sub, env, desc_,
          case when desc_>0 then c.codigo end, sub - desc_ + env, datos->>'paypal_id', datos->>'notas');
  return jsonb_build_object('ref', r, 'total', sub - desc_ + env, 'envio', env, 'descuento', desc_);
end $$;
revoke all on function crear_pedido(jsonb) from public;
grant execute on function crear_pedido(jsonb) to anon, authenticated;

-- ---------- CANCELAR PEDIDO (devuelve el stock) ----------
create or replace function cancelar_pedido(pref text) returns void
language plpgsql security definer set search_path = public as $$
declare pe pedidos%rowtype; l jsonb;
begin
  if not puede_editar() then raise exception 'Sin permiso'; end if;
  select * into pe from pedidos where ref = pref for update;
  if not found or pe.estado = 'cancelado' then return; end if;
  for l in select * from jsonb_array_elements(pe.lineas) loop
    update productos set uds = uds + (l->>'q')::numeric where id = l->>'id';
    insert into movimientos (producto,cantidad,motivo,quien) values (l->>'id',(l->>'q')::numeric,'Pedido '||pref||' cancelado',
      (select nombre from admins where user_id = auth.uid()));
  end loop;
  update pedidos set estado = 'cancelado' where ref = pref;
end $$;
revoke all on function cancelar_pedido(text) from public, anon;
grant execute on function cancelar_pedido(text) to authenticated;

-- ---------- PRIMER ADMINISTRADOR ----------
-- Todos los usuarios creados en Authentication → Users pasan a ser administradores.
insert into admins (user_id, nombre, rol)
select id, split_part(email,'@',1), 'admin' from auth.users
on conflict (user_id) do nothing;

